use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\TenantTermsOfUseVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Application\Usecase\Update\TenantTermsOfUseUpdateParams;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Application\Usecase\Update\TenantTermsOfUseUpdateResult;

class TenantTermsOfUseUpdateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly TenantTermsOfUseUpdateUsecase $updateUsecase,
        private readonly Context $context,
        private readonly MagicLinkService $links,
    ) {
    }
    #[OA\Put(
        path: "/api/access/tenants-terms-of-use/{uid}",
        tags: ["Tenant terms of use"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TenantTermsOfUseApiDTO")),
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TenantTermsOfUseApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
        new OA\Response(response: 409, description: "Optimist lock"),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function update(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Update Tenant terms of use");
        $span = $this->startSpan("Update Tenant terms of use");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $value = $this->readTenantTermsOfUse($request);
            $result = $this->updateUsecase->update($uid, $value);
            $this->sql->commit();
            $value = $this->mapTenantTermsOfUse($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readTenantTermsOfUse(ServerRequestInterface $request): TenantTermsOfUseUpdateParams
    {
        $this->logDebug("Read entity for Tenant terms of use");
        $span = $this->startSpan("Read entity for Tenant terms of use");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new TenantTermsOfUseUpdateParams();
            $valueUid = TenantTermsOfUseUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('tenant', array_keys($body))) {
                $valueTenant = TenantTermsOfUseTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList);
                if (null !== $valueTenant) {
                    $value->tenant($valueTenant);
                }
            }
            if (in_array('relyingParty', array_keys($body))) {
                $value->relyingParty(TenantTermsOfUseRelyingPartyVO::tryFrom(isset($body['relyingParty']['$ref']) ? new RelyingPartyRef($body['relyingParty']['$ref']) : null, $errorsList));
            }
            $valueText = TenantTermsOfUseTextVO::tryFrom($body['text'] ?? null, $errorsList);
            if (null !== $valueText) {
                $value->text($valueText);
            }
            $attached = $body['attached'] ?? null;
            $preffixAttached = $this->context->getBaseUrl() . '/api/access/tenants-terms-of-use/-/temp-attached?temp=';
            if (null !== $attached && strpos($attached, $preffixAttached) === 0) {
                $value->attached(TenantTermsOfUseAttachedVO::tryFromTemporal(base64_decode(substr($attached, strlen($preffixAttached))), $errorsList));
            }
            $value->activationDate(TenantTermsOfUseActivationDateVO::tryFrom($body['activationDate'] ?? null, $errorsList));
            $value->version(TenantTermsOfUseVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapTenantTermsOfUse(ServerRequestInterface $request, TenantTermsOfUseUpdateResult $value): TenantTermsOfUseApiDTO
    {
        $this->logDebug("Map entity to output dto for Tenant terms of use");
        $span = $this->startSpan("Map entity to output dto for Tenant terms of use");
        try {
            $tenant = $value->getTenant();
            $relyingParty = $value->getRelyingParty();
            $dto = new TenantTermsOfUseApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->relyingParty = $relyingParty ? ['$ref' => $relyingParty->uid()] : null;
            $dto->text = $value->getText();
            $dto->enabled = $value->isEnabled();
            if (null !== $value->getAttached()) {
                $url = $this->context->getBaseUrl() . '/api/access/tenants-terms-of-use/' . ($value->getUid() ?? '-'). '/attached';
                $dto->attached = $this->links->create($url, $request);
            }
            $dto->activationDate = $value->getActivationDate()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
